python3 -c "
import re
with open('/tmp/clock_samples/sample_11.txt') as f:
    raw = f.read()
lines = raw.split('\n')
for i, line in enumerate(lines[:7]):
    line2 = line.replace('\x1b[42m', '\x01').replace('\x1b[49m', '\x02')
    line2 = line2.replace('\x0e', '').replace('\x0f', '')
    m = re.match(r'^x(.*?)x +$', line2)
    if m:
        content = m.group(1)
        row = []
        in_block = False
        for ch in content:
            if ch == '\x01':
                in_block = True
            elif ch == '\x02':
                in_block = False
            elif ch == ' ':
                row.append('#' if in_block else '.')
            else:
                row.append('?')
        print(f'R{i}: len={len(row)} |{\"\".join(row)}|')
    else:
        print(f'R{i}: border/other: {line2!r}')
"

