  if (tc.datewin)  { delwin(tc.datewin);  tc.datewin = NULL; }
  if (!isendwin()) endwin();
  if (tc.screen) { delscreen(tc.screen); tc.screen = NULL; }
  if (tc.ttyf_in && tc.ttyf_in != stdin) fclose(tc.ttyf_in);
