/* Compute clock dimensions based on current options */
static void compute_clock_size(void) {
  /* 6 digits with seconds, 4 without. Digits are NUMBER_W wide with 1-col gap.
   * Colon area: 6 cols each (2-col dot + padding). */
  /* Width breakdown:
   *   HH = digit + gap + digit = 6+1+6 = 13
   *   MM/SS same
   *   colon area = 6 cols
   *   With seconds: 13 + 6 + 13 + 6 + 13 = 51, +1 trailing, +2 borders = 54
   *   Without seconds: 13 + 6 + 13 = 32, +1 trailing, +2 borders = 35
   */
  if (tc.option_seconds) {
    tc.clock_w = 54;
  } else {
    tc.clock_w = 35;
