  int max_y = tc.terminal_h - tc.clock_h - (tc.option_hide_date ? 0 : (tc.date_h - 1));

  if (tc.option_center) {
    tc.clock_x = (tc.terminal_w - tc.clock_w) / 2;
    tc.clock_y = (tc.terminal_h - tc.clock_h) / 2;
  } else if (first_time) {
    tc.clock_x = 0;
    tc.clock_y = 0;
  }
  if (tc.clock_x < min_x) tc.clock_x = min_x;
  if (tc.clock_y < min_y) tc.clock_y = min_y;
  if (tc.clock_x > max_x) tc.clock_x = max_x;
  if (tc.clock_y > max_y) tc.clock_y = max_y;

  /* Date position: centered under clock, overlapping by 1 row */
  tc.date_x = tc.clock_x + tc.clock_w / 2 - tc.date_w / 2;
  tc.date_y = tc.clock_y + tc.clock_h - 1;
  (void)max_x; (void)max_y;
}

static void update_date_string(void) {
  struct tm tmv;
  time_t t = time(NULL);
  if (tc.option_utc) gmtime_r(&t, &tmv);
  else localtime_r(&t, &tmv);
  strftime(tc.datestr, sizeof(tc.datestr), tc.date_format, &tmv);
  if (tc.option_twelve) {
    size_t n = strlen(tc.datestr);
    const char *suf = (tmv.tm_hour < 12) ? " [AM]" : " [PM]";
    if (n + strlen(suf) < sizeof(tc.datestr))
      strcat(tc.datestr, suf);
  }
}

static void compute_now(void) {
  struct tm tmv;
  time_t t = time(NULL);
  if (tc.option_utc) gmtime_r(&t, &tmv);
  else localtime_r(&t, &tmv);
  tc.now.second = tmv.tm_sec;
  tc.now.minute = tmv.tm_min;
  if (tc.option_twelve) {
    int h = tmv.tm_hour % 12;
    if (h == 0) h = 12;
    tc.now.hour = h;
  } else {
    tc.now.hour = tmv.tm_hour;
  }
}

/* Draw a single digit block at position (y,x) in window win */
static void draw_digit(WINDOW *win, int y, int x, int digit) {
  int r, c;
  for (r = 0; r < NUMBER_H; r++) {
    for (c = 0; c < NUMBER_W; c++) {
      if (digit_font[digit][r][c]) {
        mvwaddch(win, y + r, x + c, ' ' | COLOR_PAIR(1));
      } else {
        mvwaddch(win, y + r, x + c, ' ');
      }
    }
  }
}

/* Draw colon (dots) at position (y,x) spanning 6 cols area, dots at cols 2-3 */
static void draw_colon(WINDOW *win, int y, int x, int visible) {
  int attr = visible ? COLOR_PAIR(1) : COLOR_PAIR(2);
  /* row 1 dot */
  mvwaddch(win, y + 1, x + 2, ' ' | attr);
  mvwaddch(win, y + 1, x + 3, ' ' | attr);
  /* row 3 dot */
  mvwaddch(win, y + 3, x + 2, ' ' | attr);
  mvwaddch(win, y + 3, x + 3, ' ' | attr);
}

/* Positions for digits and colons inside the clock window (1-indexed for border):
 *   H1 at col 1, H2 at col 8, colon at col 14, M1 at col 20, M2 at col 27, colon at col 33, S1 at col 39, S2 at col 46
 */
static void draw_clock_contents(void) {
  WINDOW *w = tc.framewin;
  int ybase = 1; /* one row padding from top border */
  int col_h1 = 1, col_h2 = 8, col_c1 = 14, col_m1 = 20, col_m2 = 27;
  int col_c2 = 33, col_s1 = 39, col_s2 = 46;

  draw_digit(w, ybase, col_h1, tc.now.hour / 10);
  draw_digit(w, ybase, col_h2, tc.now.hour % 10);
  draw_colon(w, ybase, col_c1, tc.colon_visible);
  draw_digit(w, ybase, col_m1, tc.now.minute / 10);
  draw_digit(w, ybase, col_m2, tc.now.minute % 10);

  if (tc.option_seconds) {
    draw_colon(w, ybase, col_c2, tc.colon_visible);
    draw_digit(w, ybase, col_s1, tc.now.second / 10);
    draw_digit(w, ybase, col_s2, tc.now.second % 10);
  }
}

static void draw_clock_box(void) {
  WINDOW *w = tc.framewin;
  if (tc.option_box) {
    wbkgd(w, COLOR_PAIR(0));
    box(w, 0, 0);
  } else {
    /* No borders: clear chars there */
    wbkgd(w, COLOR_PAIR(0));
  }
}

static void draw_date_box(void) {
  WINDOW *w = tc.datewin;
  wbkgd(w, COLOR_PAIR(2));
  if (tc.option_box) {
    box(w, 0, 0);
  }
  mvwprintw(w, 1, 1, "%s", tc.datestr);
}

static void rebuild_windows(void) {
  if (tc.framewin) { delwin(tc.framewin); tc.framewin = NULL; }
  if (tc.datewin)  { delwin(tc.datewin);  tc.datewin = NULL; }
  tc.framewin = newwin(tc.clock_h, tc.clock_w, tc.clock_y, tc.clock_x);
  if (!tc.option_hide_date) {
    tc.datewin = newwin(tc.date_h, tc.date_w, tc.date_y, tc.date_x);
  }
}

static void full_redraw(void) {
  clear();
  refresh();
  draw_clock_box();
  draw_clock_contents();
  wrefresh(tc.framewin);
  if (!tc.option_hide_date) {
    draw_date_box();
    wrefresh(tc.datewin);
  }
}

/* Initialize ncurses */
static void init_curses(void) {
  struct stat sb;
  if (tc.tty_arg) {
    if (stat(tc.tty_arg, &sb) == -1) {
      fprintf(stderr, "tty-clock: error: couldn't stat '%s': %s.\n", tc.tty_arg, strerror(errno));
      exit(EXIT_FAILURE);
    }
    if (!S_ISCHR(sb.st_mode)) {
      fprintf(stderr, "tty-clock: error: '%s' doesn't appear to be a character device.\n", tc.tty_arg);
      exit(EXIT_FAILURE);
    }
    tc.ttyf_in = fopen(tc.tty_arg, "r");
    tc.ttyf_out = fopen(tc.tty_arg, "w");
    if (!tc.ttyf_in || !tc.ttyf_out) {
      fprintf(stderr, "tty-clock: error: couldn't open '%s': %s.\n", tc.tty_arg, strerror(errno));
      exit(EXIT_FAILURE);
    }
    tc.screen = newterm(NULL, tc.ttyf_out, tc.ttyf_in);
    assert(tc.screen != NULL);
    set_term(tc.screen);
  } else {
    initscr();
  }

  cbreak();
  noecho();
  keypad(stdscr, 1);
  curs_set(0);
  nodelay(stdscr, 1);

  start_color();
  use_default_colors();

  if (tc.option_blink) {
    init_pair(0, tc.color, -1);         /* normal text */
    init_pair(1, -1, tc.color);         /* digit block */
    init_pair(2, tc.color, tc.color);   /* hidden colon */
  } else {
    init_pair(0, tc.color, -1);
    init_pair(1, -1, tc.color);
    init_pair(2, tc.color, tc.color);
  }

  if (tc.option_bold) {
    wattron(stdscr, A_BLINK);
  }

  /* terminal size */
  tc.terminal_w = COLS;
  tc.terminal_h = LINES;
}

static void handle_key(int c) {
  switch (c) {
    case 'q': case 'Q':
      if (!tc.option_noquit) tc.running = 0;
      break;
    case 's': case 'S':
      tc.option_seconds = !tc.option_seconds;
      compute_clock_size();
      compute_clock_position(0);
      rebuild_windows();
      full_redraw();
      break;
    case 't': case 'T':
      tc.option_twelve = !tc.option_twelve;
      update_date_string();
      compute_clock_size();
      compute_clock_position(0);
      rebuild_windows();
      full_redraw();
      break;
    case 'x': case 'X':
      tc.option_box = !tc.option_box;
      rebuild_windows();
      full_redraw();
      break;
    case 'c': case 'C':
      tc.option_center = !tc.option_center;
      if (!tc.option_center) {
        tc.clock_x = 0; tc.clock_y = 0;
      }
      compute_clock_position(0);
      rebuild_windows();
      full_redraw();
      break;
    case 'r': case 'R':
      tc.option_rebound = !tc.option_rebound;
      break;
    case 'b': case 'B':
      tc.option_bold = !tc.option_bold;
      if (tc.option_bold) wattron(stdscr, A_BLINK);
      else wattroff(stdscr, A_BLINK);
      full_redraw();
      break;
    case 'h': case 'H': /* left */
      if (!tc.option_center && tc.clock_x > 0) {
        tc.clock_x--;
        compute_clock_position(0);
        rebuild_windows();
        full_redraw();
      }
      break;
    case 'l': case 'L': /* right */
      if (!tc.option_center && tc.clock_x + tc.clock_w < tc.terminal_w) {
        tc.clock_x++;
        compute_clock_position(0);
        rebuild_windows();
        full_redraw();
      }
      break;
    case 'k': case 'K': /* up */
      if (!tc.option_center && tc.clock_y > 0) {
        tc.clock_y--;
        compute_clock_position(0);
        rebuild_windows();
        full_redraw();
      }
      break;
    case 'j': case 'J': /* down */
      if (!tc.option_center && tc.clock_y + tc.clock_h + (tc.option_hide_date?0:(tc.date_h-1)) < tc.terminal_h) {
        tc.clock_y++;
        compute_clock_position(0);
        rebuild_windows();
        full_redraw();
      }
      break;
    case '0': case '1': case '2': case '3':
    case '4': case '5': case '6': case '7':
      tc.color = c - '0';
      init_pair(1, -1, tc.color);
      init_pair(0, tc.color, -1);
      init_pair(2, tc.color, tc.color);
      full_redraw();
      break;
    default:
      if (tc.option_screensaver && !tc.option_noquit) tc.running = 0;
      break;
  }
}

static void tick_rebound(void) {
  if (!tc.option_rebound || tc.option_center) return;
  int max_x = tc.terminal_w - tc.clock_w;
  int max_y = tc.terminal_h - tc.clock_h - (tc.option_hide_date ? 0 : (tc.date_h - 1));
  tc.clock_x += tc.rebound_dx;
  tc.clock_y += tc.rebound_dy;
  if (tc.clock_x < 0) { tc.clock_x = 0; tc.rebound_dx = -tc.rebound_dx; }
  if (tc.clock_y < 0) { tc.clock_y = 0; tc.rebound_dy = -tc.rebound_dy; }
  if (tc.clock_x > max_x) { tc.clock_x = max_x; tc.rebound_dx = -tc.rebound_dx; }
  if (tc.clock_y > max_y) { tc.clock_y = max_y; tc.rebound_dy = -tc.rebound_dy; }
  compute_clock_position(0);
  rebuild_windows();
  full_redraw();
}

int main(int argc, char *argv[]) {
  /* defaults */
  tc.option_center = 0;
  tc.option_box = 0;
  tc.option_rebound = 0;
  tc.option_twelve = 0;
  tc.option_utc = 0;
  tc.option_seconds = 0;
  tc.option_screensaver = 0;
  tc.option_noquit = 0;
  tc.option_bold = 0;
  tc.option_blink = 0;
  tc.option_hide_date = 0;
  tc.color = COLOR_GREEN;
  tc.delay = 1;
  tc.nsdelay = 0;
  tc.date_format = "%F";
  tc.tty_arg = NULL;
  tc.colon_visible = 1;
  tc.rebound_dx = 1;
  tc.rebound_dy = 1;
  tc.running = 1;

  int c;
  while ((c = getopt(argc, argv, "iuvsScbtrahDBxnC:f:d:a:T:")) != -1) {
    switch (c) {
      case 'h':
        print_help();
        return 0;
      case 'v':
        print_version();
        return 0;
      case 'i':
        print_info();
        return 0;
      case 's': tc.option_seconds = 1; break;
      case 'S': tc.option_screensaver = 1; break;
      case 'c': tc.option_center = 1; break;
      case 'b': tc.option_bold = 1; break;
      case 't': tc.option_twelve = 1; break;
      case 'r': tc.option_rebound = 1; break;
      case 'x': tc.option_box = 1; break;
      case 'u': tc.option_utc = 1; break;
      case 'n': tc.option_noquit = 1; break;
      case 'D': tc.option_hide_date = 1; break;
      case 'B': tc.option_blink = 1; break;
      case 'a': tc.nsdelay = atol(optarg); break;
      case 'd': tc.delay = atoi(optarg); break;
      case 'f': tc.date_format = optarg; break;
      case 'C': tc.color = atoi(optarg); break;
      case 'T': tc.tty_arg = optarg; break;
      case '?': default:
        print_help();
        return 0;
    }
  }

  /* Initialize */
  compute_now();
  update_date_string();
  init_curses();

  if (tc.terminal_w < 40 || tc.terminal_h < 10) {
    /* minimal size sanity */
  }

  compute_clock_size();
  compute_clock_position(1);

  rebuild_windows();

  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  full_redraw();

  /* Main loop */
  struct timespec req;
  while (tc.running) {
    compute_now();
    update_date_string();

    /* Update clock digits */
    draw_clock_box();
    draw_clock_contents();
    wrefresh(tc.framewin);
    if (!tc.option_hide_date) {
      draw_date_box();
      wrefresh(tc.datewin);
    }

    /* Toggle blinking colon */
    if (tc.option_blink) tc.colon_visible = !tc.colon_visible;

    /* Delay */
    req.tv_sec = tc.delay;
    req.tv_nsec = tc.nsdelay;
    /* Use nanosleep but break on signal */
    nanosleep(&req, NULL);

    /* Rebound */
    if (tc.option_rebound) tick_rebound();

    /* Poll key */
    int ch = wgetch(stdscr);
    if (ch != -1 && ch != ERR) {
      handle_key(ch);
      if (tc.option_screensaver && !tc.option_noquit) {
        tc.running = 0;
      }
    }
  }

  cleanup();
  return 0;
}
